{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e3-attempts-t5/cell-zHZa0t/src/errors.js","content":"/**
 * Error types used by the build-schedule CLI.
 *
 * `CliError` carries the exit code (2) that every "every other failure"
 * message uses. `CycleError` carries the cycle path found during dependency
 * validation and always maps to exit code 3.
 */

export class CliError extends Error {
  constructor(message) {
    super(message)
    this.name = 'CliError'
  }
}

export class CycleError extends Error {
  constructor(path) {
    super(`cycle: ${path.join(' -> ')}`)
    this.name = 'CycleError'
    this.path = path
  }
}
"}

