chunk.argumentsDelta:
{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e3-attempts-t5/cell-zHZa0t/src/parse.js","content":"/**
 * Parses the textual build-graph format described in the task prompt into a
 * `Graph` structure: a map of task names to their cost, in declaration
 * order, and a map of task names to the set of names they depend on.
 */

import { CliError } from './errors.js'

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

export function parseGraph(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map() // name -> cost
  const order = [] // declaration order
  const depEdges = [] // { head, deps, line } in the order they were read

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new CliError(`line ${lineNumber}: expected task <name> <cost>`)
      }
      const [, name, costStr] = words
      if (!NAME_RE.test(name)) {
        throw new CliError(`line ${lineNumber}: invalid task name ${name}`)
      }
      if (!COST_RE.test(costStr)) {
        throw new CliError(`line ${lineNumber}: cost must be a non-negative integer`)
      }
      if (tasks.has(name)) {
        throw new CliError(`line ${lineNumber}: task ${name} is declared twice`)
      }
      tasks.set(name, parseInt(costStr, 10))
      order.push(name)
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new CliError(`line ${lineNumber}: expected dep <name> <dependency>...`)
      }
      const head = words[1]
      const deps = words.slice(2)
      depEdges.push({ head, deps, line: lineNumber })
    } else {
      throw new CliError(`line ${lineNumber}: unknown directive ${directive}`)
    }
  }

  // Every name a dep line uses must be a declared task. Check in input
  // order: line by line, the head first, then each dependency in order.
  for (const edge of depEdges) {
    if (!tasks.has(edge.head)) {
      throw new CliError(`unknown task ${edge.head}`, true)
    }
    for (const dep of edge.deps) {
      if (!tasks.has(dep)) {
        throw new CliError(`unknown task ${dep}`, true)
      }
    }
  }

  const deps = new Map()
  for (const name of order) deps.set(name, new Set())
  for (const edge of depEdges) {
    const set = deps.get(edge.head)
    for (const dep of edge.deps) set.add(dep)
  }

  return { tasks, order, deps }
}
"}

