chunk.argumentsDelta:
{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e3-attempts-t5/cell-zHZa0t/src/graph.js","content":"/**
 * Analysis over a parsed build graph: cycle detection, unlimited-worker
 * timing (start/finish/depth per task), and the downstream priority used by
 * the worker-packing simulation.
 */

import { CycleError } from './errors.js'

function cmpName(a, b) {
  return a < b ? -1 : a > b ? 1 : 0
}

/**
 * Finds the first cycle a depth-first search encounters when visiting
 * tasks, and each task's dependencies, in ascending name order. Throws a
 * `CycleError` if one is found.
 */
export function checkForCycle(tasks, deps) {
  const names = [...tasks.keys()].sort(cmpName)
  const visited = new Set()
  const stack = []
  const onStack = new Set()

  function dfs(node) {
    stack.push(node)
    onStack.add(node)
    const children = [...deps.get(node)].sort(cmpName)
    for (const child of children) {
      if (onStack.has(child)) {
        const idx = stack.indexOf(child)
        const cyclePath = stack.slice(idx).concat(child)
        throw new CycleError(cyclePath)
      }
      if (!visited.has(child)) dfs(child)
    }
    onStack.delete(node)
    stack.pop()
    visited.add(node)
  }

  for (const name of names) {
    if (!visited.has(name)) dfs(name)
  }
}

/**
 * Computes, for every task, its start time, finish time and wave depth
 * under an unlimited number of workers. Assumes the graph has no cycle.
 */
export function computeTiming(tasks, deps) {
  const start = new Map()
  const finish = new Map()
  const depth = new Map()

  function calc(name) {
    if (finish.has(name)) return
    const children = deps.get(name)
    let s = 0
    let d = 0
    if (children.size > 0) {
      let maxFinish = 0
      let maxDepth = -1
      for (const child of children) {
        calc(child)
        if (finish.get(child) > maxFinish) maxFinish = finish.get(child)
        if (depth.get(child) > maxDepth) maxDepth = depth.get(child)
      }
      s = maxFinish
      d = maxDepth + 1
    }
    start.set(name, s)
    depth.set(name, d)
    finish.set(name, s + tasks.get(name))
  }

  for (const name of tasks.keys()) calc(name)

  let total = 0
  for (const f of finish.values()) if (f > total) total = f

  return { start, finish, depth, total }
}

/**
 * Computes, for every task, the cost of the longest chain that begins at it
 * and runs forward through its dependents to a task nothing depends on.
 * This is the priority used to break scheduling ties in `pack`.
 */
export function computePriority(tasks, deps) {
  const successors = new Map()
  for (const name of tasks.keys()) successors.set(name, new Set())
  for (const [head, set] of deps) {
    for (const dep of set) successors.get(dep).add(head)
  }

  const priority = new Map()

  function calc(name) {
    if (priority.has(name)) return priority.get(name)
    let best = 0
    for (const succ of successors.get(name)) {
      const p = calc(succ)
      if (p > best) best = p
    }
    const value = tasks.get(name) + best
    priority.set(name, value)
    return value
  }

  for (const name of tasks.keys()) calc(name)

  return priority
}
"}

