import { computePriority } from './graph.js'

function cmpName(a, b) {
  return a < b ? -1 : a > b ? 1 : 0
}

export function pack(tasks, deps, workerCount) {
  const priority = computePriority(tasks, deps)
  const names = [...tasks.keys()]

  const finish = new Map()
  const started = new Set()

  const workerBusyUntil = new Array(workerCount).fill(0)
  const workerLog = Array.from({ length: workerCount }, () => [])

  let t = 0
  let scheduledCount = 0
  const total = names.length

  while (scheduledCount < total) {
    let progressed = true
    while (progressed) {
      progressed = false

      const freeWorkers = []
      for (let i = 0; i < workerCount; i++) {
        if (workerBusyUntil[i] <= t) freeWorkers.push(i)
      }
      if (freeWorkers.length === 0) break

      const ready = []
      for (const name of names) {
        if (started.has(name)) continue
