      const task = ready[0]
      const workerIdx = freeWorkers[0]
      const start = t
      const fin = t + tasks.get(task)

      started.add(task)
      finish.set(task, fin)
      workerLog[workerIdx].push({ name: task, start, finish: fin })
      workerBusyUntil[workerIdx] = fin
      scheduledCount++
      progressed = true
    }

    if (scheduledCount === total) break

    let next = Infinity
    for (let i = 0; i < workerCount; i++) {
      if (workerBusyUntil[i] > t && workerBusyUntil[i] < next) next = workerBusyUntil[i]
    }
