 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { parseGraph } from './parse.js'
import { checkForCycle, computeTiming } from './graph.js'
import { pack } from './pack.js'
import { CliError, CycleError } from './errors.js'

const WORKERS_RE = /^[1-9][0-9]*$/

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require0()
  while (true) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.slice(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function require0() {
  // Using createRequire keeps this module ESM while still allowing the
  // synchronous stdin read that a line-oriented CLI needs.
  return globalThis.__cliRequire ?? (globalThis.__cliRequire = createSyncRequire())
}

function createSyncRequire() {
  const { createRequire } = /* @vite-ignore */ Object.getPrototypeOf(async () => {}).constructor
  return require
}

function parseArgs(argv) {
  if (argv.length === 1 && argv[0] === 'waves') return { mode: 'waves' }
  if (argv.length === 1 && argv[0] === 'explain') return { mode: 'explain' }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_RE.test(argv[1])) {
      throw new CliError('workers must be a positive integer')
    }
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  throw new CliError('usage: cli.js waves|explain|pack <workers>')
}

function formatWaves(tasks, timing) {
  const lines = []
  if (tasks.size > 0) {
    let maxDepth = 0
    for (const d of timing.depth.values()) if (d > maxDepth) maxDepth = d
    for (let k = 0; k <= maxDepth; k++) {
      const names = [...tasks.keys()].filter((n) => timing.depth.get(n) === k).sort()
      lines.push(`wave ${k}: ${names.join(' ')}`)
    }
  }
  lines.push(`total ${timing.total}`)
  return lines.join('\n') + '\n'
}

function formatExplain(tasks, timing) {
  const lines = []
  const names = [...tasks.keys()].sort()
  for (const name of names) {
    lines.push(
      `${name} start=${timing.start.get(name)} finish=${timing.finish.get(name)} depth=${timing.depth.get(name)}`,
    )
  }
  lines.push(`total ${timing.total}`)
  return lines.join('\n') + '\n'
}

function formatPack(result) {
  const lines = []
  result.workerLog.forEach((log, i) => {
    const parts = log.map((t) => ` ${t.name}@${t.start}-${t.finish}`).join('')
    lines.push(`worker ${i}:${parts}`)
  })
  lines.push(`makespan ${result.makespan}`)
  return lines.join('\n') + '\n'
}

