  const argv = process.argv.slice(2)
  let args
  try {
    args = parseArgs(argv)
  } catch (err) {
    if (err instanceof CliError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  const input = readStdin()

  let graph
  try {
    graph = parseGraph(input)
    checkForCycle(graph.tasks, graph.deps)
  } catch (err) {
    if (err instanceof CycleError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(3)
    }
    if (err instanceof CliError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  const { tasks, deps } = graph

  let output
  if (args.mode === 'waves') {
    output = formatWaves(tasks, computeTiming(tasks, deps))
  } else if (args.mode === 'explain') {
    output = formatExplain(tasks, computeTiming(tasks, deps))
  } else {
    output = formatPack(pack(tasks, deps, args.workers))
  }

  process.stdout.write(output)
}

